/* TOV4R Code Quest — static, browser-local learning adventure. */
'use strict';
(() => {
const $=id=>document.getElementById(id), C=QuestCore, curriculum=QuestCurriculum;
const missions=curriculum.missions, tracks=curriculum.tracks;
let KEY='tov4r-code-quest-v1',accountMode=false,demoMode=false,activeUser=null,authMode='signin',booting=false;
const cloud=QuestCloud;
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const avatars={robot:'🤖',fox:'🦊',cat:'🐱',alien:'👾'};
const worldNames={html:'Les fondations',css:'L’atelier des styles',js:'Le pouvoir du code'};
const levelNames={1:'Débutant',2:'Intermédiaire',3:'Avancé'};
const labDefaults={html:'<h1>Bienvenue dans mon labo</h1>\n<p>Essaie une nouvelle balise !</p>\n<button>Explorer</button>',css:'/* Modifie la carte de démonstration. */\n.card {\n  background: #d9f6c4;\n  color: #203c32;\n  padding: 28px;\n  border-radius: 20px;\n}\nbutton { background: #203c32; color: white; padding: 12px; border: 0; border-radius: 8px; }',js:'const aventurier = "Toi";\nconst missions = [60, 80, 100];\nconst total = missions.reduce((somme, xp) => somme + xp, 0);\nconsole.log(`Bravo ${aventurier} : ${total} XP !`);'};
const glossary=[['HTML','Le langage qui structure une page : titres, paragraphes, liens, images…'],['Balise','Un marqueur comme <p> ou <h1>. Il indique le rôle d’un contenu.'],['Attribut','Une information ajoutée à une balise. Exemple : href dans un lien.'],['CSS','Le langage qui définit l’apparence : couleurs, dimensions et mise en page.'],['Sélecteur','Ce qui désigne les éléments à styler. .card cible les éléments de classe card.'],['Flexbox','Une méthode CSS pour aligner des éléments sur une ligne ou une colonne.'],['Grid','Une méthode CSS pour organiser des éléments en lignes et colonnes.'],['Responsive','Une interface qui s’adapte à différentes tailles d’écran.'],['Variable','Un nom associé à une valeur. const score = 10 garde une valeur nommée score.'],['Fonction','Un bloc de code réutilisable qui peut recevoir des paramètres et retourner un résultat.'],['Tableau','Une liste de valeurs, par exemple [10, 20, 30]. Le premier élément a l’index 0.'],['Objet','Un ensemble de propriétés, par exemple { nom: "Nova", xp: 60 }.'],['Condition','Une décision dans le code, souvent avec if et else.'],['Boucle','Une façon de répéter une action, par exemple avec for ou for…of.'],['Console','Un espace où afficher des informations avec console.log pour comprendre son code.'],['JSON','Un format texte de données, utilisé notamment pour exporter et restaurer ta partie.']];
let state=C.initial(),currentView='adventure',setupStep=0,setup={name:'',level:1,track:'html',goal:1,avatar:'robot'},session=null,labTrack='html',activeWorker=null,workerTimer=null,toastTimer=null,saveTimer=null;
try{const raw=localStorage.getItem(KEY);if(raw)state=C.normalize(JSON.parse(raw),missions);}catch{toast('La sauvegarde locale est indisponible ou illisible. Tu peux démarrer une nouvelle aventure.');}
function save(){if(!accountMode&&!demoMode)return true;if(accountMode)cloud.stage(state);try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('Stockage indisponible. Exporte ta partie avant de fermer la page.');return false;}}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function sound(success=true){if(!state.sound)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.connect(gain);gain.connect(ctx.destination);osc.frequency.setValueAtTime(success?523:220,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(success?880:180,ctx.currentTime+.13);gain.gain.setValueAtTime(.035,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.25);osc.start();osc.stop(ctx.currentTime+.26);osc.onended=()=>ctx.close();}catch{}}
function confirmAction(title,text,yes){$('confirm-title').textContent=title;$('confirm-text').textContent=text;$('confirm-dialog').showModal();$('confirm-no').onclick=()=>$('confirm-dialog').close();$('confirm-yes').onclick=()=>{$('confirm-dialog').close();yes();};}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const box=$('celebration');box.replaceChildren();for(let i=0;i<28;i++){const p=document.createElement('i');p.className='confetti';p.style.left=Math.random()*100+'%';p.style.background=['#b4ef99','#b6a3fa','#ffd789'][i%3];p.style.animationDelay=Math.random()*.3+'s';box.append(p);}setTimeout(()=>box.replaceChildren(),2300);}
function progress(track){const list=missions.filter(m=>!track||m.track===track),done=list.filter(m=>state.completed[m.id]).length;return {done,total:list.length,percent:Math.round(100*done/list.length)};}
function rank(){const xp=C.xp(state,missions);return {level:Math.floor(xp/300)+1,percent:(xp%300)/3,xp,next:300-xp%300,title:xp>=1800?'Architecte du web':xp>=900?'Créateur en route':xp>=300?'Apprenti du code':'Explorateur du web'};}
function daily(){return Object.values(state.completed).filter(c=>c.date===C.today()).length;}
function badgeList(){const count=progress().done,xp=C.xp(state,missions),stars=Object.values(state.completed).reduce((n,c)=>n+c.stars,0);return [{icon:'🌱',title:'Premier pas',text:'Termine ta toute première mission.',done:count>=1},{icon:'🔥',title:'Sur ta lancée',text:'Termine 5 missions différentes.',done:count>=5},{icon:'🏛️',title:'Bâtisseur HTML',text:'Termine les 10 missions HTML.',done:progress('html').done===10},{icon:'🎨',title:'Artiste CSS',text:'Termine les 10 missions CSS.',done:progress('css').done===10},{icon:'⚡',title:'Esprit logique',text:'Termine les 10 missions JavaScript.',done:progress('js').done===10},{icon:'⭐',title:'Collection d’étoiles',text:'Réunis 15 étoiles dans tes missions.',done:stars>=15},{icon:'💎',title:'Le cap des 1 000',text:'Gagne au moins 1 000 XP.',done:xp>=1000},{icon:'👑',title:'La grande aventure',text:'Termine les 30 missions.',done:count===30}];}
function setupRender(){
 $('step-count').textContent=String(setupStep+1).padStart(2,'0')+' / 03';document.querySelectorAll('.step-dots>span').forEach((d,i)=>d.classList.toggle('on',i<=setupStep));$('setup-back').hidden=setupStep===0;$('setup-error').textContent='';$('setup-next').innerHTML=setupStep===2?'Lancer mon aventure <span>↗</span>':'Continuer <span>↗</span>';
 if(setupStep===0)$('setup-content').innerHTML=`<p class="eyebrow">BIENVENUE, FUTUR CRÉATEUR</p><h1>Apprends le code.<br><span>Joue ton aventure.</span></h1><p class="muted">Pas besoin de tout savoir. On part de ton niveau et on avance, une mission à la fois.</p><label class="field" for="player-name">Comment doit-on t’appeler ?<input id="player-name" maxlength="24" autocomplete="nickname" value="${esc(setup.name)}" placeholder="Ton pseudo d’explorateur"></label><p class="muted">Quel est ton niveau aujourd’hui ?</p><div class="choices">${[[1,'🌱','Je pars de zéro','Je découvre le code, guide-moi pas à pas.'],[2,'🧩','J’ai quelques bases','Je connais les notions simples et je veux pratiquer.'],[3,'🚀','Je veux me challenger','Je suis à l’aise avec les bases, allons plus loin.']].map(([n,icon,title,desc])=>choice('level',n,icon,title,desc,setup.level===n)).join('')}</div>`;
 if(setupStep===1)$('setup-content').innerHTML=`<p class="eyebrow">CHOISIS TON PREMIER MONDE</p><h1>Par où veux-tu<br><span>commencer ?</span></h1><p class="muted">Les trois mondes restent accessibles. Ton choix détermine simplement le début de ton parcours.</p><div class="choices">${tracks.map(t=>choice('track',t.id,t.icon,t.title+' · '+worldNames[t.id],t.description,setup.track===t.id)).join('')}</div><p class="muted" style="margin-top:20px">🌱 Si tu débutes, commence par HTML, puis CSS et JavaScript.</p>`;
 if(setupStep===2)$('setup-content').innerHTML=`<p class="eyebrow">UNE AVENTURE À TON RYTHME</p><h1>Un petit effort.<br><span>De vrais progrès.</span></h1><p class="muted">Choisis ton objectif quotidien. Aucun chrono, aucune vie à perdre : tu peux toujours réessayer.</p><div class="choices">${[[1,'☕','1 mission par jour','Environ 5 à 10 minutes, pour prendre le rythme.'],[2,'⚡','2 missions par jour','Environ 10 à 20 minutes, pour avancer régulièrement.'],[3,'🔥','3 missions par jour','Environ 20 à 30 minutes, pour aller plus loin.']].map(([n,icon,title,desc])=>choice('goal',n,icon,title,desc,setup.goal===n)).join('')}</div><p class="muted" style="margin:22px 0 8px">Et ton compagnon d’aventure ?</p><div class="avatar-choices">${Object.entries(avatars).map(([id,icon])=>`<button type="button" class="avatar-choice ${setup.avatar===id?'selected':''}" data-setup="avatar" data-value="${id}" aria-label="Avatar ${id}" aria-pressed="${setup.avatar===id}">${icon}</button>`).join('')}</div>`;
}
function choice(field,value,icon,title,desc,selected){return `<button type="button" class="choice ${selected?'selected':''}" data-setup="${field}" data-value="${value}" aria-pressed="${selected}"><span class="choice-icon">${icon}</span><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span><i class="choice-check" aria-hidden="true"></i></button>`;}
$('setup-content').addEventListener('click',e=>{const b=e.target.closest('[data-setup]');if(!b)return;const name=$('player-name');if(name)setup.name=name.value;const field=b.dataset.setup;setup[field]=['level','goal'].includes(field)?Number(b.dataset.value):b.dataset.value;setupRender();});
$('setup-next').onclick=()=>{const name=$('player-name');if(name)setup.name=name.value.trim();if(!setup.name){$('setup-error').textContent='Choisis un pseudo pour démarrer.';name?.focus();return;}if(setupStep<2){setupStep++;setupRender();return;}state.profile={...setup};state.lastTrack=setup.track;save();showGame();openMission(C.recommend(state,missions));};
$('setup-back').onclick=()=>{setupStep=Math.max(0,setupStep-1);setupRender();};
function updateTopbar(){updateSync();const r=rank();$('xp-count').textContent=r.xp;$('streak-count').textContent=C.streak(state);$('profile-shortcut').textContent=avatars[state.profile?.avatar]||'🤖';$('sound-toggle').setAttribute('aria-pressed',String(state.sound));$('sound-toggle').setAttribute('aria-label',state.sound?'Couper les sons':'Activer les sons');}
function showGame(){$('auth-screen').hidden=true;$('storage-label').textContent=accountMode?'Sauvegarde privée en ligne':'Démo · progression locale';$('setup-screen').hidden=true;$('game-screen').hidden=false;updateTopbar();render('adventure',false);}
function worldCard(t){const p=progress(t.id);return `<article class="world-card ${t.id}"><img class="world-card-image" src="assets/${t.id}-island.webp" alt="L’île du monde ${t.title}" width="560" height="500"><div class="world-card-content"><span class="world-type">MONDE ${tracks.indexOf(t)+1} / ${t.title.toUpperCase()}</span><h3>${worldNames[t.id]}</h3><p>${esc(t.description)}</p><div class="world-progress"><span>${p.done} / ${p.total} missions</span><span>${p.percent}%</span></div><div class="progress-track" role="progressbar" aria-label="Progression ${t.title}" aria-valuenow="${p.percent}" aria-valuemin="0" aria-valuemax="100"><span style="width:${p.percent}%"></span></div><button class="world-button" data-action="world" data-track="${t.id}">${p.done?'Continuer':'Explorer le monde'} <span>↗</span></button></div></article>`;}
function render(view=currentView,focus=true){currentView=view;updateTopbar();document.querySelectorAll('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const names={adventure:'MON AVENTURE',map:'CARTE DES MISSIONS',playground:'LABORATOIRE LIBRE',badges:'MES RÉCOMPENSES',glossary:'PETIT LEXIQUE',profile:'MON PROFIL'};$('breadcrumb').textContent=names[view]||names.adventure;
 const fn={adventure:renderAdventure,map:renderMap,playground:renderPlayground,badges:renderBadges,glossary:renderGlossary,profile:renderProfile}[view]||renderAdventure;$('main-content').innerHTML=fn();if(view==='playground'){bindEditor('lab-editor',code=>{state.drafts['lab-'+labTrack]=code;});renderPreview(labTrack,state.drafts['lab-'+labTrack]??labDefaults[labTrack],'lab-preview',false);}if(focus)$('main-content').focus({preventScroll:true});}
function renderAdventure(){const r=rank(),p=progress();const activity=Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-6+i);const key=C.today(date),done=missions.filter(m=>state.completed[m.id]?.date===key);return {date:key,label:date.toLocaleDateString('fr-FR',{weekday:'short'}),count:done.length,xp:done.reduce((n,m)=>n+m.xp,0)};});return QuestPremium.dashboard({name:state.profile.name,avatar:avatars[state.profile.avatar],xp:r.xp,playerLevel:r.level,completed:p.done,total:p.total,streak:C.streak(state),goal:state.profile.goal,todayCount:daily(),trackStats:tracks.map((t,i)=>({id:t.id,title:t.title,...progress(t.id),color:['#b4ef99','#b6a3fa','#ffd789'][i]})).map(t=>({...t,done:t.done})),activity,nextMission:C.recommend(state,missions),syncLabel:accountMode?'Compte personnel · sauvegarde en ligne':'Mode démo · cet appareil'})+`<section class="premium-worlds"><div class="section-heading"><h2>Trois mondes à explorer</h2><button class="text-button" data-action="navigate" data-view="map">Voir la carte ↗</button></div><div class="worlds">${tracks.map(worldCard).join('')}</div></section>`;}
function renderMap(){const t=tracks.find(x=>x.id===state.lastTrack),p=progress(t.id);return `<div class="page-intro"><div><p class="eyebrow">CHOISIS TON PROCHAIN PAS</p><h1>La carte de ton aventure.</h1><p>Lis, joue, puis construis. Les missions se débloquent au fil de tes réussites.</p></div><span class="pill">${progress().done}/30 missions</span></div><div class="track-tabs">${tracks.map(x=>`<button class="track-tab ${x.id===t.id?'active':''}" data-action="track" data-track="${x.id}" aria-pressed="${x.id===t.id}">${x.icon} ${x.title}</button>`).join('')}</div><section class="track-intro"><img src="assets/${t.id}-island.webp" alt="L’île ${t.title}"><div><p class="eyebrow">MONDE ${tracks.indexOf(t)+1} / ${p.percent}% EXPLORÉ</p><h2>${worldNames[t.id]}</h2><p>${esc(t.description)}<br>Les missions de révision restent accessibles selon ton niveau de départ.</p></div></section>${[1,2,3].map(level=>`<section class="level-group"><h3>${['I / Premiers pas','II / Prendre confiance','III / Aller plus loin'][level-1]}</h3><div class="mission-list">${missions.filter(m=>m.track===t.id&&m.level===level).map(m=>{const done=state.completed[m.id],open=C.unlocked(m,state,missions);return `<button class="mission-card ${done?'complete':''} ${!open?'locked':''}" data-action="mission" data-id="${m.id}" ${!open?'disabled':''}><span class="mission-node">${done?'✓':!open?'⌑':m.id.split('-')[1]}</span><span><strong>${esc(m.title)}</strong><small>${m.estimatedMinutes} min · ${esc(m.subtitle)}</small></span><span class="mission-end">${done?'★'.repeat(done.stars):'+'+m.xp+' XP'}</span></button>`;}).join('')}</div></section>`).join('')}`;}
function renderBadges(){const badges=badgeList();return `<div class="page-intro"><div><p class="eyebrow">TES PETITES ET GRANDES VICTOIRES</p><h1>Ça mérite une récompense.</h1><p>Des badges gagnés en apprenant, sans classement inventé.</p></div><span class="pill">${badges.filter(b=>b.done).length} / ${badges.length} badges</span></div><div class="badge-grid">${badges.map(b=>`<article class="badge-card ${b.done?'':'locked'}"><span class="badge-icon">${b.icon}</span><h3>${b.title}</h3><p>${b.text}</p><span class="pill">${b.done?'✓ Débloqué':'À découvrir'}</span></article>`).join('')}</div>`;}
function renderGlossary(query=''){const found=glossary.filter(([title,text])=>(title+' '+text).toLocaleLowerCase('fr').includes(query.toLocaleLowerCase('fr')));return `<div class="page-intro"><div><p class="eyebrow">UN MOT INCONNU ?</p><h1>Le petit lexique du code.</h1><p>Des explications simples pour continuer sans te perdre.</p></div></div><label class="muted" for="glossary-search">Rechercher un mot</label><input class="search-field" id="glossary-search" type="search" placeholder="Balise, fonction, flexbox…" value="${esc(query)}"><div class="glossary-grid" id="glossary-results">${glossaryCards(found)}</div>`;}
function glossaryCards(items){return items.length?items.map(([title,text])=>`<article class="glossary-card"><h3>${esc(title)}</h3><p>${esc(text)}</p></article>`).join(''):'<p class="empty-note">Aucun mot trouvé. Essaie un autre terme.</p>';}
function renderLocalProfile(){const r=rank(),p=progress(),badges=badgeList();return `<div class="page-intro"><div><p class="eyebrow">TON AVANCÉE, TES RÉGLAGES</p><h1>Un explorateur unique.</h1><p>Retrouve tes résultats et garde une copie de ta partie.</p></div></div><div class="profile-layout"><section class="panel"><div class="profile-identity"><span class="profile-avatar">${avatars[state.profile.avatar]}</span><div><h2>${esc(state.profile.name)}</h2><p>${r.title} · Niveau ${r.level}</p></div></div><div class="profile-stats"><div class="profile-stat"><strong>${r.xp}</strong><small>XP gagnés</small></div><div class="profile-stat"><strong>${p.done}/30</strong><small>Missions terminées</small></div><div class="profile-stat"><strong>${badges.filter(b=>b.done).length}</strong><small>Badges débloqués</small></div></div><p class="muted">Les XP sont attribués une seule fois par mission. Rejouer améliore tes étoiles sans multiplier les points.</p><div class="backup-section"><h3>Ta sauvegarde t’appartient.</h3><p class="muted">Ton profil est enregistré dans ce navigateur. Exporte une copie JSON pour conserver ta progression ou la retrouver sur un autre appareil.</p><div class="backup-actions"><button class="button secondary" data-action="export">Exporter ma partie ↓</button><button class="button ghost" data-action="import">Restaurer une partie ↑</button></div></div></section><section class="panel"><h3>Les réglages de ton aventure</h3><form id="profile-form" class="settings-form"><label for="edit-name">Pseudo<input id="edit-name" maxlength="24" required value="${esc(state.profile.name)}"></label><label for="edit-level">Niveau de départ<select id="edit-level">${[1,2,3].map(n=>`<option value="${n}" ${state.profile.level===n?'selected':''}>${levelNames[n]}</option>`).join('')}</select></label><label for="edit-goal">Objectif quotidien<select id="edit-goal">${[1,2,3].map(n=>`<option value="${n}" ${state.profile.goal===n?'selected':''}>${n} mission${n>1?'s':''} par jour</option>`).join('')}</select></label><label for="edit-avatar">Avatar<select id="edit-avatar">${Object.entries(avatars).map(([id,icon])=>`<option value="${id}" ${state.profile.avatar===id?'selected':''}>${icon} ${id}</option>`).join('')}</select></label><button class="button primary" type="submit">Enregistrer les réglages ✓</button></form><div class="backup-section"><h3>Une nouvelle aventure ?</h3><p class="muted">Tu peux recommencer avec un profil vide. Exporte ta partie d’abord si tu veux la garder.</p><button class="button danger small" data-action="reset">Recommencer l’aventure</button></div><button class="text-button" data-action="navigate" data-view="glossary" style="margin-top:24px">Ouvrir le petit lexique ↗</button></section></div>`;}
function renderProfile(){let html=renderLocalProfile();if(accountMode){html=html.replace('Ton profil est enregistré dans ce navigateur. Exporte une copie JSON pour conserver ta progression ou la retrouver sur un autre appareil.','Ton compte conserve tes missions et tes brouillons en ligne. Connecte-toi avec la même adresse sur un autre appareil. Une copie JSON reste disponible.').replace('Une nouvelle aventure ?','Ton compte').replace('Tu peux recommencer avec un profil vide. Exporte ta partie d’abord si tu veux la garder.','Déconnecte-toi pour changer de compte. Ta progression reste conservée en ligne.').replace('data-action="reset">Recommencer l’aventure','data-action="logout">Se déconnecter');html=`<section class="panel account-chip"><div><strong>Compte personnel</strong><p>${esc(activeUser.email||'Compte connecté')}</p></div><button class="button ghost small" data-action="sync">Synchroniser ↻</button><button class="button ghost small" data-action="migrate">Importer ma démo locale</button></section>`+html;}else html=`<section class="panel account-chip"><div><strong>Tu explores la démo</strong><p>Crée un compte pour conserver tes progrès en ligne.</p></div><button class="button primary small" data-action="account">Créer mon compte ↗</button></section>`+html;return html;}
function renderPlayground(){return `<div class="page-intro"><div><p class="eyebrow">EXPÉRIMENTER, C’EST APPRENDRE</p><h1>Ton laboratoire libre.</h1><p>Pas de note, pas d’XP. Juste un espace pour essayer tes idées.</p></div></div><div class="lab-tabs">${tracks.map(t=>`<button class="track-tab ${t.id===labTrack?'active':''}" data-action="lab-track" data-track="${t.id}" aria-pressed="${t.id===labTrack}">${t.title}</button>`).join('')}</div><p class="muted">${labTrack==='js'?'JavaScript de base dans une console isolée : variables, fonctions et tableaux. Les API DOM comme document ne sont pas disponibles.':labTrack==='css'?'Écris du CSS pour la carte de démonstration. L’aperçu te montre le résultat.':'Écris du HTML. L’aperçu affiche ta structure dans une zone séparée.'}</p>${editorMarkup('lab-editor',state.drafts['lab-'+labTrack]??labDefaults[labTrack],'lab-preview',labTrack)}<div class="editor-actions"><button class="button primary small" data-action="lab-run">▶ Exécuter</button><button class="button ghost small" data-action="lab-reset">Remettre l’exemple</button><button class="button ghost small" data-action="navigate" data-view="glossary">Lexique ↗</button></div><p class="validation-note">${accountMode?'Tes brouillons sont synchronisés avec ton compte.':'Les essais restent dans ton navigateur.'} HTML/CSS : aperçu séparé. JavaScript : console en Worker, arrêt automatique après 2 secondes. Ctrl/⌘ + Entrée pour exécuter.</p>`;}
function editorMarkup(id,code,preview,track){return `<div class="editor-grid"><section class="editor-box"><div class="editor-toolbar"><span>${track==='html'?'index.html':track==='css'?'style.css':'script.js'}</span><span>${accountMode?'BROUILLON SYNCHRONISÉ':'BROUILLON LOCAL'}</span></div><label for="${id}" class="skip">Éditeur de code ${track.toUpperCase()}</label><textarea id="${id}" class="code-editor" spellcheck="false" autocapitalize="off" autocomplete="off" aria-label="Éditeur de code ${track.toUpperCase()}" maxlength="20000">${esc(code)}</textarea></section><section class="preview-box"><div class="editor-toolbar"><span>${track==='js'?'CONSOLE JAVASCRIPT':'APERÇU DU RÉSULTAT'}</span><span>LOCAL</span></div><div id="${preview}"></div></section></div>`;}
function bindEditor(id,onChange){const editor=$(id);if(!editor)return;editor.addEventListener('input',()=>{onChange(editor.value);clearTimeout(saveTimer);saveTimer=setTimeout(save,350);});editor.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const start=editor.selectionStart,end=editor.selectionEnd;editor.setRangeText('  ',start,end,'end');editor.dispatchEvent(new Event('input',{bubbles:true}));}if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();if(id==='mission-editor')runChallenge();else runLab();}});}
const robotSVG='<svg xmlns="http://www.w3.org/2000/svg" width="160" height="140" viewBox="0 0 160 140"><rect x="30" y="30" width="100" height="75" rx="22" fill="#b4ef99"/><rect x="40" y="42" width="80" height="48" rx="15" fill="#18343c"/><circle cx="62" cy="62" r="7" fill="#a8f5e0"/><circle cx="98" cy="62" r="7" fill="#a8f5e0"/><path d="M68 79q12 12 24 0" fill="none" stroke="#a8f5e0" stroke-width="4"/><path d="M80 30V16" stroke="#b4ef99" stroke-width="6"/><circle cx="80" cy="12" r="7" fill="#a8f5e0"/></svg>';
const robotData='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(robotSVG);
const fixture=`<main><section class="card"><span class="badge">NOUVELLE QUÊTE</span><h1>Un monde à créer</h1><p>Apprends le code, un petit pas à la fois.</p><div class="actions"><button class="button">Explorer</button><button>En savoir plus</button></div></section><div class="gallery"><article>HTML</article><article>CSS</article><article>JavaScript</article></div><div class="quests"><div class="quest">Mission 01</div><div class="quest">Mission 02</div><div class="quest">Mission 03</div></div><img class="robot" src="${robotData}" alt="Robot explorateur" width="90" height="85"></main>`;
let pendingWorker=null;
function stopWorker(){clearTimeout(workerTimer);if(activeWorker){activeWorker.terminate();activeWorker=null;}if(pendingWorker){const resolve=pendingWorker;pendingWorker=null;resolve({success:false,cancelled:true});}}
function renderPreview(track,code,target,executeJS=true){const box=$(target);if(!box)return Promise.resolve({success:false,cancelled:true});box.replaceChildren();if(track!=='js'){
 const frame=document.createElement('iframe');frame.title='Aperçu du code '+track.toUpperCase();frame.setAttribute('sandbox','');frame.referrerPolicy='no-referrer';const fixed=code.replace(/src\s*=\s*(["'])(?:assets\/)?robot\.svg\1/gi,'src="'+robotData+'"');
 const base='<style>body{font-family:system-ui,sans-serif;color:#203444;background:#fff;padding:24px;margin:0}h1{font-size:28px}p{line-height:1.8}button{cursor:pointer}.gallery,.quests{margin-top:20px}.gallery>*,.quest{padding:12px;background:#eef1f7;border:1px solid #d8dfe8}.badge{display:inline-block;font-size:10px;padding:6px;background:#eee9ff}.robot{margin-top:18px}</style>';
 frame.srcdoc='<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; img-src data:; base-uri \'none\'; form-action \'none\'"><meta name="viewport" content="width=device-width,initial-scale=1">'+base+(track==='css'?'<style>'+code+'</style>':'')+'</head><body>'+(track==='css'?fixture:fixed)+'</body></html>';box.append(frame);return Promise.resolve({success:true});
 }
 const output=document.createElement('pre');output.className='console-output';output.setAttribute('aria-label','Sortie de la console');output.textContent=executeJS?'Exécution…':'Clique sur « Exécuter » pour lancer ton JavaScript.';box.append(output);if(!executeJS)return Promise.resolve({success:true});stopWorker();
 return new Promise(resolve=>{let finished=false,lines=0;pendingWorker=resolve;const source=`'use strict';\nconst send=(...args)=>self.postMessage({kind:'log',text:args.map(x=>{try{return typeof x==='string'?x:JSON.stringify(x)??String(x);}catch{return String(x);}}).join(' ').slice(0,2000)});\nself.console={log:send,info:send,warn:send,error:send,table:send};\ntry{\n(function(){\n${code}\n})();\nself.postMessage({kind:'done'});\n}catch(error){self.postMessage({kind:'error',text:String(error.name+': '+error.message).slice(0,500)});}`;
 const blob=new Blob([source],{type:'application/javascript'}),url=URL.createObjectURL(blob);let worker;
 function end(result){if(finished)return;finished=true;clearTimeout(workerTimer);worker?.terminate();if(activeWorker===worker)activeWorker=null;pendingWorker=null;URL.revokeObjectURL(url);resolve(result);}
 try{worker=new Worker(url);activeWorker=worker;output.textContent='';worker.onmessage=e=>{if(e.data?.kind==='log'){if(lines<40){output.textContent+=e.data.text+'\n';lines++;}}else if(e.data?.kind==='error'){output.textContent+='✗ '+e.data.text;end({success:false,error:e.data.text});}else if(e.data?.kind==='done'){if(!lines)output.textContent='✓ Exécution terminée. Ajoute console.log(...) pour afficher une valeur.';else output.textContent+='\n✓ Exécution terminée.';end({success:true});}};worker.onerror=e=>{e.preventDefault();const error=(e.message||'Erreur de syntaxe JavaScript').slice(0,500);output.textContent='✗ '+error;end({success:false,error});};workerTimer=setTimeout(()=>{output.textContent+='\n✗ Arrêt après 2 secondes. Vérifie tes boucles et réessaie.';end({success:false,error:'Temps d’exécution dépassé.'});},2000);}catch(error){output.textContent='Impossible de démarrer la console : '+error.message;end({success:false,error:error.message});}
 });
}
function openMission(mission){if(!mission||!C.unlocked(mission,state,missions)){toast('Termine la mission précédente pour débloquer celle-ci.');return;}stopWorker();state.lastTrack=mission.track;save();session={mission,tab:'lesson',lessonRead:false,quizCorrect:false,quizAttempts:0,selection:null,lastWrong:null,hints:0,revealed:false,code:state.drafts[mission.id]??mission.challenge.starter,codePassed:false};$('mission-kicker').textContent=mission.track.toUpperCase()+' / '+levelNames[mission.level].toUpperCase()+' · '+mission.estimatedMinutes+' MIN · '+mission.xp+' XP';$('mission-title').textContent=mission.title;renderMission();$('mission-dialog').showModal();}
function closeMission(){stopWorker();if(session){state.drafts[session.mission.id]=session.code;save();}session=null;$('mission-dialog').close();render(currentView,false);}
$('mission-close').onclick=closeMission;$('mission-dialog').addEventListener('cancel',e=>{e.preventDefault();closeMission();});
function setMissionTab(tab){if(!session)return;stopWorker();session.tab=tab;renderMission();}
function renderMission(){if(!session)return;for(const button of document.querySelectorAll('[data-tab]'))button.setAttribute('aria-selected',String(button.dataset.tab===session.tab));const fn={lesson:renderLesson,quiz:renderQuiz,code:renderChallenge,complete:renderComplete}[session.tab];$('mission-body').innerHTML=fn();if(session.tab==='code'){bindEditor('mission-editor',code=>{session.code=code;state.drafts[session.mission.id]=code;session.codePassed=false;const complete=$('complete-mission');if(complete)complete.disabled=true;if($('code-checks'))$('code-checks').replaceChildren();});renderPreview(session.mission.type,session.code,'mission-preview',false);}}
function renderLesson(){const m=session.mission;return `<section class="lesson-layout" role="tabpanel" aria-labelledby="tab-lesson"><div class="lesson-copy"><div class="concept-tags">${m.concepts.map(t=>`<span>${esc(t)}</span>`).join('')}</div><p>${esc(m.lesson)}</p><div class="mission-bottom"><p>Lis l’exemple, puis teste tes réflexes avec une question.</p><button class="button primary small" data-mission="understood">J’ai compris, à moi de jouer →</button></div></div><aside><img class="lesson-art" src="assets/${m.track}-island.webp" alt="Le monde ${m.track.toUpperCase()}"><h3 style="font-size:12px;margin-top:20px">Un exemple pour comprendre</h3><pre class="code-block"><code>${esc(m.example)}</code></pre></aside></section>`;}
function renderQuiz(){const m=session.mission,q=m.quiz;return `<section class="quiz-content" role="tabpanel" aria-labelledby="tab-quiz"><p class="eyebrow">UN PETIT DÉFI POUR FIXER L’IDÉE</p><h3>${esc(q.question)}</h3><div class="quiz-options">${q.options.map((option,i)=>`<button class="quiz-option ${session.quizCorrect&&i===q.answer?'correct':''} ${session.lastWrong===i&&!session.quizCorrect?'incorrect':''}" data-mission="select" data-index="${i}" aria-pressed="${session.selection===i}" ${session.quizCorrect?'disabled':''} style="${session.selection===i&&!session.quizCorrect?'border-color:#a6c58b':''}"><span class="letter">${'ABCD'[i]}</span><span>${esc(option)}</span></button>`).join('')}</div>${session.quizCorrect?`<p class="quiz-feedback">✓ Bien joué ! ${esc(q.explanation)}</p><button class="button primary" data-mission="to-code">Construire avec du code →</button>`:`${session.lastWrong!==null?'<p class="quiz-feedback wrong">Pas encore ! Relis la question et essaie une autre réponse. Tu peux revenir à la leçon, sans perdre de vie.</p>':''}<button class="button primary" data-mission="check-quiz" ${session.selection===null?'disabled':''}>Valider ma réponse ✓</button>`}<p class="validation-note">Le nombre d’essais influence les étoiles, jamais ton droit de continuer.</p></section>`;}
function renderChallenge(){const m=session.mission;return `<section role="tabpanel" aria-labelledby="tab-code"><p class="eyebrow">À TOI DE CONSTRUIRE</p><p class="code-challenge-prompt">${esc(m.challenge.prompt)}</p>${editorMarkup('mission-editor',session.code,'mission-preview',m.type)}<div class="editor-actions"><button class="button primary small" data-mission="run">▶ Exécuter & vérifier</button><button class="button ghost small" data-mission="hint">✦ Un indice (${session.hints}/${m.challenge.hints.length})</button><button class="button ghost small" data-mission="reset-code">Repartir du début</button><button class="button ghost small" data-mission="solution">Voir une solution</button></div><div id="hint-area">${session.hints?'<p class="hint-box">'+m.challenge.hints.slice(0,session.hints).map(esc).join('\n')+'</p>':''}</div><div id="code-checks" class="checks" aria-live="polite"></div><p class="validation-note">Contrôles pédagogiques basés sur le code attendu, pas une vérification exhaustive. ${m.type==='js'?'Le JavaScript s’exécute en Worker sans document ni window.':'L’aperçu HTML/CSS est isolé de l’application.'} Ctrl/⌘ + Entrée : exécuter.</p><div class="mission-bottom"><p id="completion-help">${!session.lessonRead?'Marque d’abord la leçon comme comprise.':!session.quizCorrect?'Valide aussi la question avant de terminer.':'Exécute et réussis les contrôles pour terminer la mission.'}</p><button class="button primary small" id="complete-mission" data-mission="finish" ${!(session.codePassed&&session.lessonRead&&session.quizCorrect)?'disabled':''}>Terminer la mission ✦</button></div></section>`;}
async function runChallenge(){if(!session||session.tab!=='code')return;const attempt=session,code=$('mission-editor').value;attempt.code=code;state.drafts[attempt.mission.id]=code;save();attempt.codePassed=false;$('complete-mission').disabled=true;$('code-checks').innerHTML='<p class="muted">Vérification en cours…</p>';const checks=C.checkCode(code,attempt.mission);const execution=await renderPreview(attempt.mission.type,code,'mission-preview',true);if(session!==attempt||attempt.tab!=='code'||attempt.code!==code||execution.cancelled)return;if(attempt.mission.type==='js')checks.push({label:execution.success?'JavaScript exécuté sans erreur.':execution.error,passed:execution.success});attempt.codePassed=checks.every(c=>c.passed);$('code-checks').innerHTML=checks.map(c=>`<div class="check ${c.passed?'pass':''}"><span>${c.passed?'✓':'○'}</span>${esc(c.label)}</div>`).join('');$('complete-mission').disabled=!(attempt.codePassed&&attempt.lessonRead&&attempt.quizCorrect);$('completion-help').textContent=attempt.codePassed?(attempt.lessonRead&&attempt.quizCorrect?'Tout est validé. Ta mission est prête à être terminée !':'Code réussi ! Valide aussi la leçon et la question.'):"Presque ! Regarde les points à compléter et essaie encore.";sound(attempt.codePassed);}
function renderComplete(){const m=session.mission,c=state.completed[m.id],next=C.recommend(state,missions,m.track);return `<section class="completion-view"><p class="eyebrow">UNE NOUVELLE ÉTAPE FRANCHIE</p><div class="big-medal">${m.id.endsWith('10')?'🏆':'🎉'}</div><h3>${m.id.endsWith('10')?'Un monde exploré. Bravo !':'Mission accomplie !'}</h3><div class="completion-stars" aria-label="${c.stars} étoiles sur 3">${'★'.repeat(c.stars)}${'☆'.repeat(3-c.stars)}</div><div class="completion-reward">${session.justAwarded?'+'+m.xp+' XP':'Mission rejouée · étoiles mises à jour'}</div><p>Tu viens de terminer « ${esc(m.title)} ». Chaque petit exercice te rapproche d’un projet que tu peux créer toi-même.</p><p class="validation-note">3 étoiles : quiz réussi au premier essai et aucun indice. Une solution consultée donne 1 étoile pour cet essai. Le meilleur score est conservé.</p><button class="button primary" data-mission="next" data-id="${next.id}">${progress(m.track).done===10?'Explorer un autre monde':'Prochaine mission'} →</button><button class="button ghost" data-mission="close">Retour à mon aventure</button></section>`;}
$('mission-dialog').addEventListener('click',async e=>{const tab=e.target.closest('[data-tab]');if(tab){setMissionTab(tab.dataset.tab);return;}const b=e.target.closest('[data-mission]');if(!b||!session)return;const action=b.dataset.mission,m=session.mission;
 if(action==='understood'){session.lessonRead=true;setMissionTab('quiz');}
 if(action==='select'){session.selection=Number(b.dataset.index);renderMission();}
 if(action==='check-quiz'){if(session.selection===null)return;session.quizAttempts++;session.quizCorrect=session.selection===m.quiz.answer;session.lastWrong=session.quizCorrect?null:session.selection;sound(session.quizCorrect);renderMission();}
 if(action==='to-code')setMissionTab('code');if(action==='run')runChallenge();
 if(action==='hint'){session.hints=Math.min(m.challenge.hints.length,session.hints+1);$('hint-area').innerHTML='<p class="hint-box">'+m.challenge.hints.slice(0,session.hints).map(esc).join('\n')+'</p>';b.textContent=`✦ Un indice (${session.hints}/${m.challenge.hints.length})`;}
 if(action==='solution')confirmAction('Voir une solution ?','Essaie d’abord avec les indices. Si tu consultes la solution, cet essai pourra gagner une étoile ; tu pourras rejouer pour en gagner davantage.',()=>{if(!session||session.mission.id!==m.id)return;session.revealed=true;session.code=m.challenge.solution;state.drafts[m.id]=session.code;save();renderMission();});
 if(action==='reset-code')confirmAction('Repartir du début ?','Ton brouillon de cette mission sera remplacé par le code de départ.',()=>{if(!session||session.mission.id!==m.id)return;session.code=m.challenge.starter;session.codePassed=false;state.drafts[m.id]=session.code;save();renderMission();});
 if(action==='finish'){if(!(session.codePassed&&session.lessonRead&&session.quizCorrect)||session.saving)return;const attempt=session;attempt.saving=true;b.disabled=true;b.textContent='Enregistrement…';try{if(accountMode){const c=await cloud.complete({missionId:m.id,code:attempt.code,lessonRead:attempt.lessonRead,quizAnswer:attempt.selection,quizAttempts:attempt.quizAttempts,hints:attempt.hints,revealed:attempt.revealed});if(session!==attempt)return;if(c.queued){toast('Mission en attente de connexion. Les XP seront ajoutés après validation en ligne.');b.textContent='Réessayer la synchronisation';return;}attempt.justAwarded=applyCompletion(c);}else{const stars=attempt.revealed?1:Math.max(1,3-(attempt.quizAttempts>1?1:0)-(attempt.hints>0?1:0));attempt.justAwarded=C.award(state,m,stars);}save();attempt.tab='complete';sound(true);celebrate();updateTopbar();renderMission();}catch(error){toast(error.message==='MISSION_LOCKED'?'Termine la mission précédente avant de continuer.':'Enregistrement refusé. Vérifie ta connexion et réessaie.');}finally{attempt.saving=false;if(b.isConnected)b.disabled=false;}}
 if(action==='next'){if(progress(m.track).done===10){closeMission();render('map');}else openMission(missions.find(x=>x.id===b.dataset.id));}
 if(action==='close')closeMission();
});
function exportState(){const data=JSON.stringify(state,null,2),url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='tov4r-code-quest-'+C.today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Une copie de ta partie a été préparée. Garde-la pour restaurer ta progression.');}
function runLab(){const editor=$('lab-editor');if(!editor)return;state.drafts['lab-'+labTrack]=editor.value;save();renderPreview(labTrack,editor.value,'lab-preview',true);}
$('main-content').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='navigate'){stopWorker();render(b.dataset.view);}
 if(a==='mission')openMission(missions.find(m=>m.id===b.dataset.id));
 if(a==='world'||a==='track'){stopWorker();state.lastTrack=b.dataset.track;save();render('map');}
 if(a==='lab-track'){stopWorker();labTrack=b.dataset.track;render('playground',false);}
 if(a==='lab-run')runLab();if(a==='lab-reset')confirmAction('Remettre l’exemple ?','Le brouillon de ce langage sera remplacé par l’exemple de départ.',()=>{state.drafts['lab-'+labTrack]=labDefaults[labTrack];save();render('playground',false);});
 if(a==='export')exportState();if(a==='import')$('import-file').click();
 if(a==='logout'){signOut();return;}if(a==='sync'){syncNow();return;}if(a==='account'){save();showAuth('signup');return;}if(a==='migrate'){migrateDemo();return;}
 if(a==='reset')confirmAction('Recommencer l’aventure ?','Ton profil et ta progression enregistrés dans ce navigateur seront remplacés par une nouvelle partie. Tu peux annuler pour exporter une copie d’abord.',()=>{stopWorker();state=C.initial();save();setupStep=0;setup={name:'',level:1,track:'html',goal:1,avatar:'robot'};$('game-screen').hidden=true;$('setup-screen').hidden=false;setupRender();window.scrollTo(0,0);});
});
$('main-content').addEventListener('input',e=>{if(e.target.id==='glossary-search'){const q=e.target.value.toLocaleLowerCase('fr');$('glossary-results').innerHTML=glossaryCards(glossary.filter(([title,text])=>(title+' '+text).toLocaleLowerCase('fr').includes(q)));}});
$('main-content').addEventListener('submit',e=>{if(e.target.id!=='profile-form')return;e.preventDefault();const name=$('edit-name').value.trim();if(!name){toast('Choisis un pseudo non vide.');return;}state.profile={...state.profile,name,level:Number($('edit-level').value),goal:Number($('edit-goal').value),avatar:$('edit-avatar').value};save();render('profile',false);toast('Tes réglages sont enregistrés.');});
for(const el of document.querySelectorAll('.sidebar [data-view]'))el.addEventListener('click',e=>{e.preventDefault();stopWorker();render(el.dataset.view);});
$('profile-shortcut').onclick=()=>{stopWorker();render('profile');};$('sound-toggle').onclick=()=>{state.sound=!state.sound;save();updateTopbar();sound();};$('export-shortcut').onclick=exportState;
$('import-file').onchange=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;if(file.size>500000){toast('Ce fichier est trop volumineux pour une partie Code Quest.');return;}try{const imported=C.normalize(JSON.parse(await file.text()),missions);if(!imported.profile)throw new Error('Cette sauvegarde ne contient pas encore de profil.');if(accountMode){confirmAction('Importer cette sauvegarde ?','Les brouillons seront importés. Les missions seront revérifiées en ligne ; les réussites déjà sauvegardées restent conservées.',()=>importAccount(imported));return;}confirmAction('Restaurer cette partie ?',`La partie de ${imported.profile.name} (${Object.keys(imported.completed).length} missions) remplacera la progression actuelle de ce navigateur.`,()=>{stopWorker();state=imported;save();showGame();toast('Partie restaurée. Bon retour dans l’aventure !');});}catch(error){toast('Import refusé : '+error.message);}};
window.addEventListener('beforeunload',()=>{if(session)state.drafts[session.mission.id]=session.code;save();});
function updateSync(){const el=$('sync-status');if(!el)return;const labels={connecting:'Connexion…',synced:'✓ Sauvegardé',pending:'À synchroniser',syncing:'Synchronisation…',offline:'Hors connexion',error:'Réessayer la synchro',signedout:'Démo locale'};el.textContent=accountMode?(labels[cloud.status]||'Connexion…'):'Démo locale';el.className='sync-status '+(accountMode&&['pending','offline','syncing'].includes(cloud.status)?'pending':accountMode&&cloud.status==='error'?'error':'');el.title=accountMode?(cloud.lastError||'Synchroniser mes données en ligne'):'Créer un compte pour sauvegarder en ligne';}
function applyCompletion(c){const mission=missions.find(m=>m.id===c.mission_id);if(!mission||!activeUser)return false;const first=C.award(state,mission,c.stars,c.date);try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}return first;}
function showAuth(mode='signin'){demoMode=false;stopWorker();if($('mission-dialog').open)closeMission();$('setup-screen').hidden=true;$('game-screen').hidden=true;$('auth-screen').hidden=false;setAuthMode(mode);}
function setAuthMode(mode){authMode=mode;const recovery=mode==='recovery',reset=mode==='reset';$('auth-signin').classList.toggle('active',mode==='signin');$('auth-signup').classList.toggle('active',mode==='signup');$('auth-email').disabled=recovery;$('auth-email').parentElement.hidden=recovery;$('auth-password-label').hidden=reset;$('auth-password').disabled=reset;$('auth-password').autocomplete=mode==='signin'?'current-password':'new-password';$('auth-password').minLength=mode==='signin'?1:8;$('auth-submit').textContent=({signin:'Entrer dans mon aventure →',signup:'Créer mon compte →',reset:'Envoyer le lien de récupération',recovery:'Enregistrer mon nouveau mot de passe'})[mode];$('auth-submit').disabled=false;$('auth-message').textContent='';$('auth-error').textContent='';$('auth-forgot').hidden=reset||recovery;}
function authError(error){const text=String(error?.message||'');if(/Invalid login credentials/i.test(text))return 'Email ou mot de passe incorrect.';if(/Email not confirmed/i.test(text))return 'Confirme ton adresse avec le lien reçu par email, puis connecte-toi.';if(/rate limit|too many/i.test(text))return 'Trop de tentatives. Patiente un moment avant de réessayer.';if(/password/i.test(text))return 'Le mot de passe doit contenir au moins 8 caractères.';if(/already registered/i.test(text))return 'Ce compte existe déjà. Utilise la connexion.';return 'Connexion indisponible. Vérifie le réseau et réessaie.';}
async function activate(user){if(booting||activeUser?.id===user.id&&accountMode)return;booting=true;accountMode=true;activeUser=user;KEY='tov4r-codequest-v2:'+user.id;cloud.attach(user);$('auth-message').textContent='Chargement de ta progression…';$('auth-submit').disabled=true;try{state=await cloud.load();if(state.profile){save();showGame();cloud.flush();}else{state=C.initial();setupStep=0;setup={name:'',level:1,track:'html',goal:1,avatar:'robot'};$('auth-screen').hidden=true;$('game-screen').hidden=true;$('setup-screen').hidden=false;setupRender();}}catch{activeUser=null;accountMode=false;cloud.attach(null);$('auth-error').textContent='Impossible de charger ta progression en ligne. Réessaie pour éviter d’écraser tes données.';$('auth-message').textContent='';$('auth-submit').disabled=false;}finally{booting=false;}}
async function bootstrap(){cloud.on('status',updateSync);cloud.on('rejected',()=>toast('Une mission en attente doit être rejouée : la validation en ligne a échoué.'));cloud.on('completion',c=>{if(!accountMode)return;applyCompletion(c);updateTopbar();if(!session)render(currentView,false);toast('Mission synchronisée. Tes XP sont sauvegardés.');});cloud.on('auth',async({event,user})=>{if(event==='PASSWORD_RECOVERY'){showAuth('recovery');return;}if(event==='SIGNED_OUT'){activeUser=null;accountMode=false;cloud.attach(null);state=C.initial();showAuth();return;}if(user&&event!=='INITIAL_SESSION'&&authMode!=='recovery')activate(user);});try{const result=await cloud.ready;if(result.error)throw result.error;const user=result.data.session?.user;if(user){if(cloud.recoveryRequested){showAuth('recovery');return;}await activate(user);}else setAuthMode('signin');}catch{setAuthMode('signin');$('auth-error').textContent='Impossible de contacter le service. Tu peux explorer la démo et réessayer plus tard.';}}
async function signOut(){if(accountMode){save();await cloud.flush();const {error}=await cloud.client.auth.signOut({scope:'local'});if(error){toast('Déconnexion impossible. Réessaie.');return;}}activeUser=null;accountMode=false;cloud.attach(null);state=C.initial();KEY='tov4r-code-quest-v1';showAuth();}
async function syncNow(){if(!accountMode){showAuth('signup');return;}save();await cloud.flush();if(cloud.status!=='synced'){toast('Synchronisation en attente. Tes modifications restent sur cet appareil.');return;}try{const remote=await cloud.load();state=remote;save();render(currentView,false);toast('Ta progression est à jour sur ton compte.');}catch{toast('Le chargement a échoué. Tes brouillons sont conservés.');}}
async function importAccount(data){toast('Import et vérification des missions en cours…');try{const result=await cloud.importLegacy(data);state=result.state;save();showGame();toast(`${result.imported} mission(s) vérifiée(s), ${result.skipped} à rejouer. Les imports validés valent une étoile.`);}catch{toast('Import interrompu. Les données déjà synchronisées sont conservées.');}}
function migrateDemo(){try{const source=localStorage.getItem('tov4r-code-quest-v1');if(!source){toast('Aucune partie de démo sur cet appareil.');return;}const data=C.normalize(JSON.parse(source),missions);if(!data.profile)throw new Error();confirmAction('Importer ta démo ?','Les brouillons seront importés et les missions revérifiées en ligne. Tes réussites en ligne restent conservées.',()=>importAccount(data));}catch{toast('Aucune sauvegarde de démo valide sur cet appareil.');}}
$('auth-signin').onclick=()=>setAuthMode('signin');$('auth-signup').onclick=()=>setAuthMode('signup');$('auth-forgot').onclick=()=>setAuthMode('reset');$('sync-status').onclick=syncNow;
$('demo-start').onclick=async()=>{if(activeUser){toast('Déconnecte-toi avant de lancer la démo.');return;}accountMode=false;demoMode=true;cloud.attach(null);KEY='tov4r-code-quest-v1';state=C.initial();try{const raw=localStorage.getItem(KEY);if(raw)state=C.normalize(JSON.parse(raw),missions);}catch{}$('auth-screen').hidden=true;if(state.profile)showGame();else{setupStep=0;setup={name:'',level:1,track:'html',goal:1,avatar:'robot'};$('setup-screen').hidden=false;setupRender();}};
$('auth-form').onsubmit=async e=>{e.preventDefault();const mode=authMode,email=$('auth-email').value.trim(),password=$('auth-password').value;$('auth-submit').disabled=true;$('auth-error').textContent='';$('auth-message').textContent='Connexion au service…';try{if(mode==='reset'){const {error}=await cloud.client.auth.resetPasswordForEmail(email,{redirectTo:QUEST_CONFIG.siteUrl});if(error)throw error;$('auth-message').textContent='Si un compte correspond à cette adresse, un lien de récupération vient d’être envoyé. Vérifie aussi les courriers indésirables.';}else if(mode==='recovery'){const {error}=await cloud.client.auth.updateUser({password});if(error)throw error;setAuthMode('signin');$('auth-password').value='';$('auth-message').textContent='Mot de passe enregistré. Connecte-toi pour continuer.';await cloud.client.auth.signOut({scope:'local'});}else{const result=mode==='signup'?await cloud.client.auth.signUp({email,password,options:{emailRedirectTo:QUEST_CONFIG.siteUrl}}):await cloud.client.auth.signInWithPassword({email,password});if(result.error)throw result.error;$('auth-password').value='';if(result.data.session)await activate(result.data.user);else $('auth-message').textContent='Vérifie ta boîte email et confirme ton adresse avec le lien reçu. Ensuite, reviens te connecter ici.';}}catch(error){$('auth-message').textContent='';$('auth-error').textContent=authError(error);}finally{$('auth-submit').disabled=false;}};

bootstrap();
})();
